import json, os

net = json.load(open('storage/pointer-network.json'))
router = json.load(open('storage/router.json'))

errors = []

# 1. Check all node IDs exist in their domain indexes
for nid, node in net['nodes'].items():
    domain = node['domain']
    if domain.startswith('wikipedia'):
        continue  # wiki nodes validated separately
    # Find domain index
    for d, info in router['domains'].items():
        if info.get('entry_prefix') and nid.startswith(info['entry_prefix']):
            idx = json.load(open(info['index_path']))
            ids = [e['id'] for e in idx['entries']]
            if nid not in ids:
                errors.append(f'{nid} not found in {info["index_path"]}')
            break

# 2. Check all pointers point to existing nodes
for nid, node in net['nodes'].items():
    for p in node['pointers']:
        if p['to'] not in net['nodes']:
            errors.append(f'{nid} points to non-existent {p["to"]}')

# 3. Check cluster files exist
for tag in net.get('tag_clusters', {}):
    cf = f'storage/pointer-clusters/{tag}.json'
    if not os.path.exists(cf):
        errors.append(f'Missing cluster file: {cf}')

if errors:
    print(f'{len(errors)} errors:')
    for e in errors[:20]: print(f'  {e}')
else:
    print('Pointer network is consistent')
"
